@Test
public void testVectorTransform_simple() {
    // arrange
    // rotation of zero
    Quaternion q0 = Quaternion.of(1, 0, 0, 0);
    // pi rotation around +z
    Quaternion q1 = Quaternion.of(0, 0, 0, 1);
    Slerp slerp = new Slerp(q0, q1);
    double[] vec = { 2, 0, 1 };
    // act/assert
    Assertions.assertArrayEquals(new double[] { 2, 0, 1 }, transformVector(slerp.apply(0), vec), EPS);
    Assertions.assertArrayEquals(new double[] { SQRT_2, SQRT_2, 1 }, transformVector(slerp.apply(0.25), vec), EPS);
    Assertions.assertArrayEquals(new double[] { 0, 2, 1 }, transformVector(slerp.apply(0.5), vec), EPS);
    Assertions.assertArrayEquals(new double[] { -SQRT_2, SQRT_2, 1 }, transformVector(slerp.apply(0.75), vec), EPS);
    Assertions.assertArrayEquals(new double[] { -2, 0, 1 }, transformVector(slerp.apply(1), vec), EPS);
}

@Test
public void testVectorTransform_multipleCombinations() {
    // arrange
    Quaternion[] quaternions = { // +x axis
    // 0 pi
    Quaternion.of(1, 0, 0, 0), // pi/2
    Quaternion.of(INV_SQRT_2, INV_SQRT_2, 0, 0), // pi
    Quaternion.of(0, 1, 0, 0), // -x axis
    // 0 pi
    Quaternion.of(1, 0, 0, 0), // pi/2
    Quaternion.of(INV_SQRT_2, -INV_SQRT_2, 0, 0), // pi
    Quaternion.of(0, -1, 0, 0), // +y axis
    // 0 pi
    Quaternion.of(1, 0, 0, 0), // pi/2
    Quaternion.of(INV_SQRT_2, 0, INV_SQRT_2, 0), // pi
    Quaternion.of(0, 0, 1, 0), // -y axis
    // 0 pi
    Quaternion.of(1, 0, 0, 0), // pi/2
    Quaternion.of(INV_SQRT_2, 0, -INV_SQRT_2, 0), // pi
    Quaternion.of(0, 0, -1, 0), // +z axis
    // 0 pi
    Quaternion.of(1, 0, 0, 0), // pi/2
    Quaternion.of(INV_SQRT_2, 0, 0, INV_SQRT_2), // pi
    Quaternion.of(0, 0, 0, 1), // -z axis
    // 0 pi
    Quaternion.of(1, 0, 0, 0), // pi/2
    Quaternion.of(INV_SQRT_2, 0, 0, -INV_SQRT_2), // pi
    Quaternion.of(0, 0, 0, -1) };
    // act/assert
    // test each quaternion against all of the others (including itself)
    for (int i = 0; i < quaternions.length; ++i) {
        for (int j = 0; j < quaternions.length; ++j) {
            checkSlerpCombination(quaternions[i], quaternions[j]);
        }
    }
}

