    double halfAngle1 = 0.5 * angle1;
    double halfAngle2 = 0.5 * angle2;
    // pi/4 around +z
    Quaternion q1 = Quaternion.of(Math.cos(halfAngle1), 0, 0, Math.sin(halfAngle1));
    // 3pi/4 around +z
